import json, os, subprocess, urllib.request, urllib.error

queries = {"queries": ["crisis playbook", "crisis response procedure PR",
                       "social media negative posts spike crisis", "spreadsheet ss_crisis",
                       "crisis escalation routing team", "comms alert notification comms team",
                       "post sentiment negative engagement spike",
                       "tickets route assign team social legal product",
                       "slack channel alert comms"]}
if isinstance(queries, dict):
    qlist, top_k = queries["queries"], queries.get("top_k", 5)
else:
    qlist, top_k = queries, 5

# Write a reusable MCP bridge helper so future chains can use it without re-implementing
brpath = os.path.expanduser("~/.manga-agent/world_bridge.py")
os.makedirs(os.path.dirname(brpath), exist_ok=True)
bridge = r'''
import json, urllib.request, urllib.error, sys, os

URL = "http://127.0.0.1:40573/mcp/c6bffb7649e7a8362c2f8151990fd713"
SESSION = {"id": None}

def mcp(payload):
    req = urllib.request.Request(URL, data=json.dumps(payload).encode(),
                                headers={"Content-Type": "application/json",
                                         "Accept": "application/json, text/event-stream",
                                         "MCP-Session-Id": SESSION["id"] or ""})
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            sid = r.headers.get("MCP-Session-Id")
            if sid: SESSION["id"] = sid
            return r.read().decode()
    except urllib.error.HTTPError as e:
        return "HTTPError " + str(e.code) + " " + e.read().decode()[:500]

def sse(text):
    data = [l[5:].strip() for l in text.splitlines() if l.startswith("data:")]
    return data[-1] if data else text

_counter = {"i": 100}
def call(name, args):
    _counter["i"] += 1
    raw = sse(mcp({"jsonrpc": "2.0", "id": _counter["i"], "method": "tools/call",
                   "params": {"name": name, "arguments": args}}))
    j = json.loads(raw)
    if "error" in j: return {"_err": json.dumps(j["error"])}
    c = j.get("result", {}).get("content", [])
    txt = "".join([x.get("text", "") for x in c] or [""])
    if j.get("result", {}).get("isError"):
        return {"_tool_error": txt}
    try:
        return json.loads(txt)
    except Exception:
        return txt

if __name__ == "__main__":
    name, args = sys.argv[1], json.loads(sys.argv[2])
    print(json.dumps(call(name, args), default=str))
'''
with open(brpath, "w") as f:
    f.write(bridge)
tools.write_file(path="/tmp/bridge_written.txt", content=brpath)

def api_search(query, top_k=top_k):
    out = subprocess.run(["python3", brpath, "api_search",
                          json.dumps({"query": query, "top_k": top_k})],
                         capture_output=True, text=True)
    try:
        return json.loads(out.stdout)
    except Exception:
        return out.stdout + out.stderr

res = {}
for q in qlist:
    r = api_search(q)
    res[q] = r
    s = json.dumps(r, default=str) if not isinstance(r, str) else r
    print("== ", q, " :: ", s[:1000])
    print()

json.dump(res, open("/tmp/search_results2.json", "w"), default=str)
tools.think("MCP bridge file written to " + brpath + "; searching for crisis/playbook/routing/comms endpoints next")
return res

